WITH scored AS (SELECT *, AVG(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS sqft_avg_5_prior, AVG(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS sqft_avg_5 FROM stores) SELECT id, store_name, city, region, opened_date, sqft, sqft_avg_5, CASE WHEN region RLIKE '^(North|East)$' THEN 'OTHER_ZONE' WHEN region RLIKE '^(South|West)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS region_zone FROM scored ORDER BY id NULLS LAST LIMIT 5;
